// The universal lock-free update pattern: read, compute, CAS, retry.
std::atomic<int> x{0};

void update() {
    int seen = x.load(std::memory_order_relaxed);
    int desired;
    do {
        desired = f(seen);              // pure computation on a private copy
    } while (!x.compare_exchange_weak(seen, desired));
    // on failure, 'seen' now holds the current value: recompute and retry
}

struct Node { T value; Node* next; };
std::atomic<Node*> top{nullptr};

void push(Node* n) {                    // n is private until the CAS succeeds
    Node* old = top.load(std::memory_order_relaxed);
    do {
        n->next = old;                     // link to the top we saw
    } while (!top.compare_exchange_weak(old, n,
                 std::memory_order_release,    // publish n's fields
                 std::memory_order_relaxed));
}

Node* pop() {
    Node* old = top.load(std::memory_order_acquire);
    while (old && !top.compare_exchange_weak(old, old->next,
                 std::memory_order_acquire,
                 std::memory_order_acquire))
        ;                                  // old was refreshed: retry
    return old;   // DANGER: see lesson 3 before freeing or reusing old
}

void push(Node* n) {
  Node* old = top.load(memory_order_relaxed);
  do {
    n->next = old;
  } while (!top.compare_exchange_weak(old, n,
             memory_order_release, memory_order_relaxed));
}

void enqueue(Queue* Q, T value) {
  Node* node = new_node(value); Ptr tail, next; // E1-E3
  for (;;) {
    tail = Q->Tail;                   // E5
    next = tail.ptr->next;            // E6
    if (tail != Q->Tail) continue;    // E7: consistent?
    if (next.ptr == NULL) {           // E8: tail is last
      if (CAS(&tail.ptr->next, next,
              {node, next.count + 1})) // E9: link node
        break;
    } else {                          // tail is lagging
      CAS(&Q->Tail, tail,             // E13: help swing it
          {next.ptr, tail.count + 1});
    }
  }
  CAS(&Q->Tail, tail,                 // E17: swing Tail
      {node, tail.count + 1});
}

bool dequeue(Queue* Q, T* out) {
  Ptr head, tail, next;
  for (;;) {
    head = Q->Head;                         // D2
    tail = Q->Tail;                         // D3
    next = head.ptr->next;                  // D4
    if (head != Q->Head) continue;          // D5: consistent?
    if (head.ptr == tail.ptr) {             // D6: empty or Tail lagging
      if (next.ptr == NULL) return false;   // D7-D8: really empty
      CAS(&Q->Tail, tail, {next.ptr, tail.count + 1}); // D10: help
    } else {
      *out = next.ptr->value;               // D12: read BEFORE the CAS
      if (CAS(&Q->Head, head, {next.ptr, head.count + 1})) // D13
        break;
    }
  }
  free_node(head.ptr);   // D19: old dummy (to a free list)
  return true;
}

bool enqueue(T const& data) {
  cell_t* cell;
  size_t pos = enqueue_pos_.load(memory_order_relaxed);
  for (;;) {
    cell = &buffer_[pos & buffer_mask_];
    size_t seq = cell->sequence_.load(memory_order_acquire);
    intptr_t dif = (intptr_t)seq - (intptr_t)pos;
    if (dif == 0) {                       // cell is free for this pos
      if (enqueue_pos_.compare_exchange_weak(pos, pos + 1,
                                             memory_order_relaxed))
        break;                            // claimed it
    } else if (dif < 0) {
      return false;                       // full
    } else {
      pos = enqueue_pos_.load(memory_order_relaxed); // lost race
    }
  }
  cell->data_ = data;
  cell->sequence_.store(pos + 1, memory_order_release); // publish
  return true;
}
